    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database.
        return true;
    }
}

@page "/courses"
@rendermode InteractiveServer
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject ICatalogService CatalogService

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input id="search" type="text" class="form-control" placeholder="Search by title, code, or instructor…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select id="department" class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted">Showing @filteredCourses.Count course(s)</p>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>@course.Instructor.Name</td>
                        <td>
                            <a href="@($"courses/{course.Id}")" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    private string searchTerm
    {
        get => _searchTerm;
        set
        {
            _searchTerm = value;
            FilterCourses();
        }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set
        {
            _selectedDepartmentId = value;
            FilterCourses();
        }
    }

    [SupplyParameterFromQuery]
    public int? departmentId { get; set; }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (departmentId.HasValue)
            _selectedDepartmentId = departmentId.Value;
        FilterCourses();
    }

    private void FilterCourses()
    {
        var deptFilter = _selectedDepartmentId > 0 ? (int?)_selectedDepartmentId : null;
        filteredCourses = CatalogService.GetCourses(_searchTerm, deptFilter);
    }
}

@page "/courses/{id:int}"
@using UniversityCourseCatalog.Services
